// The scraper sends an array of leads. Split into individual items.
// Normalize field names for downstream processing.
// DEDUP in-batch by lead_id (fallback phone+listing): the scraper can list the
// same inquiry in more than one tab (2026-07-01 twin-conversation bug).
// 2026-07-03: keep the BEST copy per key, not the first — a half-loaded
// duplicate without phone used to arrive first, win the dedup, and get the
// whole lead skipped for no_phone while the good copy was dropped.
const body = $input.first().json.body || $input.first().json;
const leads = Array.isArray(body) ? body : [body];

const normalize = (lead) => {
  const phone = (lead.phone || '').replace(/[^\d]/g, '');
  return {
    // Contact info
    phone,
    email: lead.email || null,
    name: lead.name || lead.pushName || null,
    message: lead.message || '',
    // Property info (already available from scraper)
    listing_id: lead.listing_id || null,
    property_title: lead.property || lead.address || 'Propiedad sin titulo',
    property_address: lead.address || '',
    property_price: lead.price || 'Precio por confirmar',
    listing_type: lead.listing_type || 'venta',
    // Scraper metadata
    property_public_id: lead.property_public_id || null,
    scraper_lead_id: lead.lead_id || null,
    source_tab: lead.source_tab || 'mensajes',
    source: 'inmuebles24'
  };
};

const best = new Map(); // key -> normalized lead
const order = [];
for (const lead of leads) {
  const n = normalize(lead);
  const key = n.scraper_lead_id ? `id:${n.scraper_lead_id}` : `pl:${n.phone}|${n.listing_id || ''}`;
  if (!best.has(key)) {
    best.set(key, n);
    order.push(key);
    continue;
  }
  const cur = best.get(key);
  // Prefer the copy that actually has contact data.
  const score = (x) => (x.phone ? 2 : 0) + (x.email ? 1 : 0);
  if (score(n) > score(cur)) best.set(key, n);
}
return order.map(k => ({ json: best.get(k) }));

// Route decision per lead. The Postgres node ("Check Returning Lead + Time")
// runs once per normalized lead and (LEFT JOIN on time_ctx) returns exactly one
// row per input item, index-aligned with "Split & Normalize Leads". So iterate
// ALL items and pair by index -- the old code used $input.first() + a single
// returned item, so a batch of >1 lead only processed the FIRST and silently
// dropped the rest.
const dbRows = $input.all();
const leads = $('Split & Normalize Leads').all();
const out = [];

for (let i = 0; i < dbRows.length; i++) {
  const db = dbRows[i].json;
  const lead = (leads[i] || leads[0]).json;

  if (!lead.phone) {
    out.push({ json: { route: 'skip', reason: 'no_phone' } });
    continue;
  }

  const isReturning = !!db.existing_conv_id;
  const sameProperty = db.same_property === true;
  const isDay = db.is_day !== false; // Default to day if query returns no rows

  if (isReturning && sameProperty) {
    out.push({ json: {
      route: 'returning_same',
      existing_conv_id: db.existing_conv_id,
      assigned_agent_id: db.assigned_agent_id,
      existing_mode: db.existing_mode,
      ...lead,
    }});
  } else if (isDay) {
    out.push({ json: {
      route: 'day_auction',
      is_returning_diff: isReturning && !sameProperty,
      ...lead,
    }});
  } else {
    out.push({ json: {
      route: 'night_queue',
      is_returning_diff: isReturning && !sameProperty,
      ...lead,
    }});
  }
}

return out;

// Notify the assigned agent about a returning lead (same property).
const data = $('Route Decision').first().json;
const conv = $input.first().json;

if (!data.assigned_agent_id) {
  return [{ json: { skip: true, reason: 'no_assigned_agent' } }];
}

return [{
  json: {
    number: data.assigned_agent_id, // Will be resolved to phone below
    conversation_id: data.existing_conv_id,
    lead_name: data.name,
    lead_phone: data.phone,
    property_title: data.property_title,
    message: `Lead recurrente: ${data.name || data.phone} volvio a preguntar por ${data.property_title}. Ya lo tienes asignado.`
  }
}];

