// Prepare data for WF3a auction call -- ONE item per lead.
// Pair each inserted conversation with its lead by i24_lead_id (fallback phone),
// NOT by array index: ON CONFLICT dedup can drop an insert mid-batch, which
// would misalign an index-based pairing.
const convs = $input.all();
const dayLeads = $('Route Decision').all().filter(r => r.json.route === 'day_auction');
const byLeadId = new Map();
const byPhone = new Map();
for (const d of dayLeads) {
  if (d.json.scraper_lead_id) byLeadId.set(String(d.json.scraper_lead_id), d.json);
  if (d.json.phone && !byPhone.has(String(d.json.phone))) byPhone.set(String(d.json.phone), d.json);
}

return convs.map(c => {
  const conv = c.json;
  const lead = (conv.i24_lead_id && byLeadId.get(String(conv.i24_lead_id)))
            || byPhone.get(String(conv.lead_phone))
            || (dayLeads[0] ? dayLeads[0].json : {});
  return {
    json: {
      // For WF3a
      conversation_id: conv.conversation_id,
      lead_phone: conv.lead_phone,
      lead_name: conv.lead_name || lead.name,
      property_id: lead.listing_id || lead.property_title || 'Sin propiedad',
      property_title: lead.property_title,
      property_price: lead.property_price,
      property_public_id: conv.property_public_id || lead.property_public_id || null,
      assigned_agent_id: null,
      // For caching
      cache_property_id: lead.listing_id || 'unknown',
      cache_payload: {
        title: lead.property_title,
        price: lead.property_price,
        location: lead.property_address,
        operation_type: lead.listing_type,
        source: 'inmuebles24_scraper'
      }
    }
  };
});

